<form method="POST" action="{{ $plan ? route('saas-ops.subscription-plans.update',$plan) : route('saas-ops.subscription-plans.store') }}" class="rounded-xl border bg-white p-5 dark:border-slate-800 dark:bg-slate-900">@csrf @if($plan) @method('PUT') @endif<div class="grid gap-4 md:grid-cols-2"><input name="code" value="{{ old('code',$plan?->code) }}" placeholder="code" class="rounded-lg dark:bg-slate-950" required><input name="name" value="{{ old('name',$plan?->name) }}" placeholder="name" class="rounded-lg dark:bg-slate-950" required><select name="billing_cycle" class="rounded-lg dark:bg-slate-950"><option value="monthly" @selected(old('billing_cycle',$plan?->billing_cycle)==='monthly')>monthly</option><option value="yearly" @selected(old('billing_cycle',$plan?->billing_cycle)==='yearly')>yearly</option></select><select name="status" class="rounded-lg dark:bg-slate-950"><option value="active" @selected(old('status',$plan?->status ?? 'active')==='active')>active</option><option value="inactive" @selected(old('status',$plan?->status)==='inactive')>inactive</option></select><input type="number" name="monthly_price" value="{{ old('monthly_price',$plan?->monthly_price ?? 0) }}" class="rounded-lg dark:bg-slate-950"><input type="number" name="yearly_price" value="{{ old('yearly_price',$plan?->yearly_price ?? 0) }}" class="rounded-lg dark:bg-slate-950"></div><textarea name="features" class="mt-4 w-full rounded-lg dark:bg-slate-950" placeholder="features per line">{{ old('features', implode("\n",$plan?->features ?? [])) }}</textarea><textarea name="notes" class="mt-4 w-full rounded-lg dark:bg-slate-950" placeholder="notes">{{ old('notes',$plan?->notes) }}</textarea><button class="mt-4 rounded-lg bg-slate-900 px-4 py-2 text-sm font-black text-white dark:bg-lime-400 dark:text-slate-950">Simpan</button></form>
